<?phpif (!defined('BASEPATH')) exit('No direct script access allowed');class mlotinspectionmodel extends CI_Model {    function fnGetInfo($VarYarn='',$VarStatus='',$VarId='') {        $this->db->select('id,level,codeletter,aql,samplesize,updatedby,status,datecreated,dateupdated'); // Select field        $this->db->from(KN_MASTER_LOTINSPECTION);        if($VarStatus<>'') {            $this->db->where_in('status',array($VarStatus));        } else {            $this->db->where_in('status',array(1,2));        }        if($VarId<>'') {            $ArrWhere['id'] 				                = $VarId;        }        if($VarYarn<>'') {            $ArrWhere['level'] 		                    = $VarYarn;        }        if(@count($ArrWhere)>=1) {            $this->db->where($ArrWhere);        }        $ArrResultList	    	    		                = $this->db->get()->result_array();        return $ArrResultList;    }    function fnCheck($VarYarn='',$VarId='') {        $this->db->select('id,level,codeletter,aql,updatedby,status,datecreated,dateupdated');        $this->db->from(KN_MASTER_LOTINSPECTION);        $ArrWhere = array('status'=>"1");        if($VarId<>'') {            $this->db->where_not_in('id',array($VarId));        }        if($VarYarn<>'') {            $ArrWhere['level']		                        = $VarYarn;        }        $this->db->where($ArrWhere);        $ObjResult  					                        = $this->db->get();        $ArrResultList					                        = $ObjResult->result_array();        return $ArrResultList;    }    function saveInfo($ArrUpdateData){        $VarId                                                  = $ArrUpdateData['id'];        if($VarId=="") {            $ArrCheckExist			       					    = $this->fnGetInfo($ArrUpdateData['level'],1);            if(@$ArrCheckExist['id']=='' && @$ArrCheckExist['id']==0) {                unset($ArrUpdateData['id']);                $this->db->insert(KN_MASTER_LOTINSPECTION,$ArrUpdateData);                $VarId                                          = $this->db->insert_id();                $ArrResult['errcode']						    = 1;                $ArrResult['msg']							    = '';                $ArrResult['id']							    = $VarId;                $ArrResult['eid']							    = urlencode(base64_encode($VarId));            } else {                $ArrResult['errcode']							= '-1';                $ArrResult['msg']								= "This yarn already exists!!";            }        } else {            $ArrCheckExist									    = $this->fnCheck($ArrUpdateData['level'],$VarId);            if(@$ArrCheckExist['id']=='' && $ArrUpdateData['level']<>'') {                if($this->db->update(KN_MASTER_LOTINSPECTION,$ArrUpdateData,array('id'=>$VarId))) {                    $ArrResult['errcode']					    = 1;                    $ArrResult['msg']							= '';                    $ArrResult['id']							= $VarId;                    $ArrResult['eid']							= urlencode(base64_encode($VarId));                } else {                    $ArrResult['errcode']						= '-1';                    $ArrResult['msg']							= 'Invalid Data!';                }            }  else {                $ArrResult['errcode']						    = '-1';                $ArrResult['msg']							    = "This level has already Exist!";            }        }        return $ArrResult;    }    function fnCount($VarYarn='',$VarStatus='',$VarAfilter=''){        $userInfo                   = fnGetUserLoggedInfo(1);        $ArrWhere                   = array();        if($VarYarn<>'') {            $ArrWhere[]             = "i.level like '%".$VarYarn."%'";        }        if($VarAfilter<>'') {            $ArrWhere[]             = "i.level LIKE '".$VarAfilter."%'";        }        if($VarStatus<>'') {            $ArrWhere[]             = "i.status=".$VarStatus;        } else {            $ArrWhere[]             = "i.status in(1,2)";        }        $ArrWhere[]                 = "i.companyid = ".$userInfo['companyid'];        $VarWhere                   = '';        if(@$ArrWhere[0]<>'') {            $VarWhere               = implode(" and ",$ArrWhere);        }            $VarSqlLab              = "SELECT count(1) as trec  FROM ".KN_MASTER_LOTINSPECTION." AS i INNER JOIN ".KN_USERS." AS u ON i.updatedby = u.id WHERE ".$VarWhere ;        $ObjRows					= $this->db->query($VarSqlLab)->row();        return $ObjRows->trec;    }    function fnList($VarYarn='',$VarStatus='',$VarLimit = 10, $offset = 0,$VarSortBy,$VarSortOrder,$VarAfilter=''){        $userInfo                   = fnGetUserLoggedInfo(1);        $VarSortOrder				= ($VarSortOrder=='desc')? 'desc' : 'asc';        $VarSortCols				= array('i.level','i.codeletter','i.aql','i.samplesize','i.status','u.contactname','i.dateupdated');        $VarSortBy					= (in_array($VarSortBy,$VarSortCols)) ? $VarSortBy : 'i.dateupdated';        $VarLimitInfo				= $VarLimit;        if($offset>=1) {$VarLimitInfo	 = $offset.",".$VarLimit;}        $ArrWhere                   = array();        if($VarYarn<>'') {            $ArrWhere[]             = "i.level like '%".$VarYarn."%'";        }        if($VarAfilter<>'') {            $ArrWhere[]             = "i.level LIKE '".$VarAfilter."%'";        }        if($VarStatus<>'') {            $ArrWhere[]             = "i.status=".$VarStatus;        } else {            $ArrWhere[]             = "i.status in(1,2)";        }        $ArrWhere[]                 = "i.companyid = ".$userInfo['companyid'];        $VarWhere                   = '';        if(@$ArrWhere[0]<>'') {            $VarWhere               = implode(" and ",$ArrWhere) ;        }        $VarSqlLab                  = "SELECT i.id,i.level,i.codeletter,i.aql,i.samplesize,u.contactname,i.datecreated,i.dateupdated,i.status FROM ".KN_MASTER_LOTINSPECTION." AS i INNER JOIN ".KN_USERS." AS u ON i.updatedby = u.id WHERE ".$VarWhere." order by ".$VarSortBy." ".$VarSortOrder." limit ".$VarLimitInfo;        $ObjResult					= $this->db->query($VarSqlLab);        return $ObjResult;    }    function fnDel($VarId='',$VarUpdatedBy='') {        if(@$VarId>=1) {            $ArrUpdateData          = array('status'=>3,'dateupdated'=>date('Y-m-d H:i:s'),'updatedby'=>$VarUpdatedBy);            if($this->db->update(KN_MASTER_LOTINSPECTION,$ArrUpdateData,array('id'=>$VarId))) {                $ArrResult['errcode']					    = 1;                $ArrResult['msg']							= '';                $ArrResult['id']							= $VarId;                $ArrResult['eid']							= urlencode(base64_encode($VarId));            } else {                $ArrResult['errcode']						= '-1';                $ArrResult['msg']							= 'Invalid Data!';            }        }        return $ArrResult;    }    function fnChangeComStat($checkboxids,$optvalue) {        $Arrids =  json_decode($checkboxids,true);        $this->db->where_in('id',$Arrids);        if($this->db->update(KN_MASTER_LOTINSPECTION,array('status' => $optvalue))) {            return true;        }        return false;    }}   